('lib/content/gpx_scolarite/dps_dpg/sanction_pages/causes_aggravation_sanction/caractere_raciste_page.dart','f00037','2.2 - La matérialisation du mobile de l’auteur',37,'_Paragraph','Le mobile raciste, xénophobe ou antisémite de l’auteur peut se matérialiser par des actes portant atteinte à l’honneur ou à la considération de la victime :','Le mobile raciste, xénophobe ou antisémite de l’auteur peut se matérialiser par des actes portant atteinte à l’honneur ou à la considération de la victime :','{}'::jsonb,true),
